import { Panel } from './ui.jsx'

// The top of an idea's page (src/qlab/plain, docs/PLAIN_PAGE.md): what the strategy does in plain
// Russian, how this variant differs from its base, how its numbers were chosen and where it was
// checked. Every text is written by a person once per family or computed by code from the spec;
// nothing here is generated by a model. The ladder, the numbers and the charts stay below.

const SOURCE_NOTE = {
  spec: 'описание из самой спецификации идеи',
  card: 'описание из карточки идеи',
  family: 'описание семейства стратегий; числа этой версии подставлены кодом из спека',
  mechanism: 'описание механизма из каталога; числа этой версии прочитаны кодом из спека',
  ancestor_card: 'описание из карточки идеи, от которой произошла эта',
  own_mechanism: 'описание механизма из спецификации идеи',
  none: 'простого описания пока нет',
}

const CHOICE_TITLE = {
  by_code: 'Числа выбирает код',
  fixed: 'Числа выбраны вручную',
  nothing_to_choose: 'Выбирать не из чего',
  unknown: 'Откуда числа — не записано',
}

function Lines({ lines }) {
  if (!lines || lines.length === 0) return null
  return (
    <ul className="mt-2 list-disc space-y-1 pl-5 text-sm text-slate-700">
      {lines.map((line, i) => (
        <li key={i}>{line}</li>
      ))}
    </ul>
  )
}

function What({ what }) {
  return (
    <Panel title="Что делает стратегия">
      <div className="space-y-3">
        {what.paragraphs.map((p, i) => (
          <p key={i} className="text-sm leading-relaxed text-slate-800">
            {p}
          </p>
        ))}
        {what.note && <p className="text-xs text-slate-500">{what.note}</p>}
        <p className="text-xs text-slate-400">{SOURCE_NOTE[what.source] ?? ''}</p>
      </div>
    </Panel>
  )
}

function Difference({ difference }) {
  if (!difference) return null
  const items = difference.items ?? []
  return (
    <Panel
      title="Чем этот вариант отличается"
      subtitle={`сравнение с основной версией (${difference.base_id}, «${difference.base_name}»)`}
    >
      {difference.is_base ? (
        <p className="text-sm text-slate-700">
          Это и есть основная версия: все числа такие же, как в образце ({difference.base_file}).
        </p>
      ) : items.length === 0 ? (
        <p className="text-sm text-slate-700">
          Отличий от основной версии нет: те же числа, те же данные.
        </p>
      ) : (
        <ul className="list-disc space-y-1 pl-5 text-sm text-slate-700">
          {items.map((item, i) => (
            <li key={i}>{item.text}</li>
          ))}
        </ul>
      )}
    </Panel>
  )
}

function Choice({ choice }) {
  if (!choice) return null
  return (
    <Panel title="Как выбраны числа" subtitle={CHOICE_TITLE[choice.kind]}>
      <p className="text-sm text-slate-700">{choice.text}</p>
      <Lines lines={choice.lines} />
    </Panel>
  )
}

function Venue({ venue }) {
  if (!venue) return null
  return (
    <Panel title="Где проверена">
      <ul className="space-y-1 text-sm text-slate-700">
        {venue.lines.map((line, i) => (
          <li key={i} className={i === venue.lines.length - 1 ? 'text-xs text-slate-500' : ''}>
            {line}
          </li>
        ))}
      </ul>
    </Panel>
  )
}

// `children` sits right under the title: the page's checklist (components/StandardPanel.jsx).
export default function PlainTop({ plain, children }) {
  if (!plain) return null
  return (
    <div className="space-y-4">
      <div>
        <h1 className="text-2xl font-semibold text-slate-900">{plain.title}</h1>
        <p className="mt-1 text-xs text-slate-500">{plain.technical_title}</p>
      </div>
      {children}
      <What what={plain.what} />
      <Difference difference={plain.difference} />
      <div className="grid gap-4 md:grid-cols-2">
        <Choice choice={plain.choice} />
        <Venue venue={plain.venue} />
      </div>
    </div>
  )
}
